def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    sandwich_patches = image_patch.find("sandwich")
    other_objects = image_patch.find("other_object")  # Assuming "other_object" is a placeholder for any other object

    if not sandwich_patches: 
        return image_patch

    if not other_objects: 
        return sandwich_patches[0]

    sandwich_depths = [(patch, patch.compute_depth()) for patch in sandwich_patches]
    other_object_depths = [(patch, patch.compute_depth()) for patch in other_objects]

    sorted_sandwiches = sorted(sandwich_depths, key=lambda x: x[1])
    sorted_others = sorted(other_object_depths, key=lambda x: x[1])

    for sandwich, _ in sorted_sandwiches:
        if all(sandwich.overlaps_with(o.left, o.lower, o.right, o.upper) for o in sorted_others):
            return sandwich

    return sandwich_patches[0]

